using System.Net.Http.Json;using BusinessPartnerPortal.Api.Data;using Microsoft.EntityFrameworkCore;
namespace BusinessPartnerPortal.Api.Services;
public sealed class OracleInvoiceOutboxWorker(IServiceProvider services,IHttpClientFactory httpFactory,IConfiguration config,ILogger<OracleInvoiceOutboxWorker> logger):BackgroundService{
 protected override async Task ExecuteAsync(CancellationToken stoppingToken){while(!stoppingToken.IsCancellationRequested){try{await Process(stoppingToken);}catch(Exception ex){logger.LogError(ex,"Outbox worker iteration failed.");}await Task.Delay(TimeSpan.FromSeconds(5),stoppingToken);}}
 async Task Process(CancellationToken ct){using var scope=services.CreateScope();var db=scope.ServiceProvider.GetRequiredService<AppDbContext>();var conn=db.Database.GetDbConnection();await conn.OpenAsync(ct);var items=new List<(Guid id,Guid invoiceId,string payload,int attempts)>();await using(var cmd=conn.CreateCommand()){cmd.CommandText="SELECT id,aggregate_id,payload::text,attempt_count FROM integration.outbox_messages WHERE status IN ('PENDING','RETRYING') AND event_type IN ('InvoiceSubmitted','InvoiceResubmitted') AND (next_attempt_at IS NULL OR next_attempt_at<=now()) ORDER BY created_at LIMIT 10";await using var rd=await cmd.ExecuteReaderAsync(ct);while(await rd.ReadAsync(ct))items.Add((rd.GetGuid(0),rd.GetGuid(1),rd.GetString(2),rd.GetInt32(3)));}
  var url=config["ORACLE_INVOICE_POST_URL"];foreach(var item in items){try{if(string.IsNullOrWhiteSpace(url)){var missing="Oracle invoice posting endpoint is not configured.";await db.Database.ExecuteSqlInterpolatedAsync($"UPDATE integration.outbox_messages SET status='FAILED',attempt_count={item.attempts+1},last_error={missing} WHERE id={item.id}",ct);continue;}var client=httpFactory.CreateClient("oracle-invoice");var req=new HttpRequestMessage(HttpMethod.Post,url){Content=JsonContent.Create(System.Text.Json.JsonSerializer.Deserialize<object>(item.payload))};if(!string.IsNullOrWhiteSpace(config["ORACLE_API_KEY"]))req.Headers.TryAddWithoutValidation("X-API-Key",config["ORACLE_API_KEY"]);var res=await client.SendAsync(req,ct);if(res.IsSuccessStatusCode){await db.Database.ExecuteSqlInterpolatedAsync($"UPDATE integration.outbox_messages SET status='PROCESSED',processed_at=now(),attempt_count={item.attempts+1},last_error=NULL WHERE id={item.id}",ct);await db.Database.ExecuteSqlInterpolatedAsync($"UPDATE invoice.invoices SET integration_status='SENT_TO_ORACLE',updated_at=now() WHERE id={item.invoiceId}",ct);}else{var msg=$"HTTP {(int)res.StatusCode} {res.ReasonPhrase}";await Retry(db,item.id,item.attempts,msg,ct);}}catch(Exception ex){await Retry(db,item.id,item.attempts,ex.Message[..Math.Min(ex.Message.Length,500)],ct);}}}
 static Task<int> Retry(AppDbContext db,Guid id,int attempts,string error,CancellationToken ct){var next=DateTimeOffset.UtcNow.AddMinutes(Math.Min(30,Math.Pow(2,Math.Min(attempts,4))));var status=attempts>=5?"FAILED":"RETRYING";return db.Database.ExecuteSqlInterpolatedAsync($"UPDATE integration.outbox_messages SET status={status},attempt_count={attempts+1},next_attempt_at={next},last_error={error} WHERE id={id}",ct);}
}
